declare(strict_types=1);$config=require __DIR__.'/../config/config.php';require_once __DIR__.'/../app/Auth.php';require_once __DIR__.'/../app/UserStorage.php';try{$u=(new Auth($config))->requireUser();$root=UserStorage::home($config,(int)$u['id']);$files=0;$bytes=0;$dirs=0;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if($f->isLink())continue;if($f->isDir()){$dirs++;continue;}$files++;$size=$f->getSize();if($size!==false)$bytes+=(int)$size;}$limit=(int)($config['limits']['max_workspace_bytes']??1073741824);$human=function(int $n):string{$units=['B','KB','MB','GB','TB'];$i=0;$v=(float)$n;while($v>=1024&&$i<count($units)-1){$v/=1024;$i++;}return number_format($v,$i?1:0,',','.').' '.$units[$i];};json_response(['ok'=>true,'files'=>$files,'directories'=>$dirs,'bytes'=>$bytes,'human_size'=>$human($bytes),'limit_bytes'=>$limit,'human_limit'=>$human($limit),'percent'=>$limit>0?round(min(100,$bytes/$limit*100),1):0]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>'Não foi possível calcular o uso do workspace.'],400);}
